<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessage} from 'element-plus/es/components/message/index'
import {ElMessageBox} from 'element-plus/es/components/message-box/index'
import {Plus,Search,Download,Refresh} from '@element-plus/icons-vue'
import {api,report} from '../api'
import {useAuth} from '../stores/auth'
import {labels,money,time,type Contract} from '../types'
const auth=useAuth(),route=useRoute(),rows=ref<Contract[]>([]),options=ref<{id:number;name:string;contact:string}[]>([]),total=ref(0),loading=ref(false),busy=ref(false),open=ref(false),detail=ref<Contract|null>(null),conflict=ref(false),detailConflict=ref(false)
const query=reactive({q:'',status:String(route.query.status??''),customer_id:Number(route.query.customer_id)||undefined,page:1,size:10})
const empty=()=>({id:0,title:'',customer_id:undefined as number|undefined,amount:'',start_date:'',end_date:'',version:1})
const form=reactive(empty())
async function load(){loading.value=true;try{const {data}=await api.get('/contracts',{params:query});rows.value=data.items;total.value=data.total}catch(e){report(e)}finally{loading.value=false}}
async function loadOptions(){try{options.value=(await api.get('/customer-options')).data}catch(e){report(e)}}
function search(){query.page=1;load()}
function fill(row:Contract){Object.assign(form,{...row,amount:(row.amount_cents/100).toFixed(2)});conflict.value=false}
async function edit(row?:Contract){await loadOptions();if(row)fill(row);else Object.assign(form,empty());conflict.value=false;open.value=true}
async function inspect(id:number){try{detail.value=(await api.get('/contracts/'+id)).data;detailConflict.value=false}catch(e){report(e)}}
async function save(){if(!form.title.trim()||!form.customer_id||!/^\d+(\.\d{1,2})?$/.test(form.amount)||!form.start_date||!form.end_date){ElMessage.warning('请填写完整信息，金额最多保留两位小数');return}const [whole,fraction='']=form.amount.split('.');const cents=Number(whole)*100+Number(fraction.padEnd(2,'0'));if(!Number.isSafeInteger(cents)||cents<=0){ElMessage.warning('请输入有效的合同金额');return}busy.value=true;try{const payload={...form,amount_cents:cents};const {data}=await(form.id?api.put('/contracts/'+form.id,payload):api.post('/contracts',payload));open.value=false;ElMessage.success('草稿已保存，可在详情中提交审核');await load();await inspect(data.id)}catch(e){conflict.value=report(e)===409}finally{busy.value=false}}
async function reloadForm(){try{await ElMessageBox.confirm('当前输入不会自动覆盖服务器数据。载入前请复制需要保留的修改。','载入最新合同',{confirmButtonText:'载入服务器版本',cancelButtonText:'保留输入'});const {data}=await api.get('/contracts/'+form.id);if(!['draft','returned'].includes(data.status)){ElMessage.warning('合同已进入审核或生效状态，无法继续编辑');open.value=false;await inspect(data.id);await load();return}fill(data)}catch(e){if(e!=='cancel'&&e!=='close')report(e)}}
const actionOpen=ref(false),actionType=ref(''),note=ref('')
const actionAllowed=computed(()=>!!detail.value&&(actionType.value==='submit'?['draft','returned'].includes(detail.value.status):auth.admin&&detail.value.status==='pending'))
function beginAction(action:string){actionType.value=action;note.value='';actionOpen.value=true}
async function act(){if(!detail.value||!actionAllowed.value)return;if(actionType.value==='return'&&!note.value.trim()){ElMessage.warning('请填写退回原因');return}busy.value=true;try{const {data}=await api.post('/contracts/'+detail.value.id+'/actions',{version:detail.value.version,action:actionType.value,note:note.value});detail.value={...data,events:detail.value.events};actionOpen.value=false;ElMessage.success('合同状态已更新');await load();await inspect(data.id)}catch(e){if(report(e)===409)detailConflict.value=true}finally{busy.value=false}}
async function exportCSV(){try{const {data}=await api.get('/contracts/export',{params:query,responseType:'blob'});const url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download='合同台账.csv';a.click();URL.revokeObjectURL(url)}catch(e){ElMessage.error('导出失败，请缩小筛选范围或稍后重试')}}
onMounted(()=>{load();loadOptions()})
</script>
<template><div class="page-heading"><div><h1>合同管理</h1><p>从草稿到生效，让每一步流转都有据可查。</p></div><el-button v-if="auth.writable" type="primary" :icon="Plus" @click="edit()">新建合同</el-button></div><section class="panel"><div class="filters"><el-input v-model="query.q" placeholder="合同名称 / 客户名称" clearable @keyup.enter="search"/><el-select v-model="query.status" placeholder="全部合同状态" clearable><el-option v-for="s in ['draft','pending','returned','active']" :key="s" :label="labels[s]" :value="s"/></el-select><el-select v-model="query.customer_id" filterable clearable placeholder="全部客户"><el-option v-for="c in options" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-button type="primary" :icon="Search" @click="search">查询</el-button><el-button :icon="Refresh" @click="Object.assign(query,{q:'',status:'',customer_id:undefined,page:1});load()">重置</el-button><el-button :icon="Download" @click="exportCSV">导出台账</el-button></div><el-table v-loading="loading" :data="rows" empty-text="暂无匹配合同，可先新建一份草稿"><el-table-column label="合同名称" min-width="230"><template #default="{row}"><button class="link" @click="inspect(row.id)">{{row.title}}</button><div class="cell-sub">CT-{{String(row.id).padStart(5,'0')}}</div></template></el-table-column><el-table-column prop="customer_name" label="关联客户" min-width="190"/><el-table-column label="合同金额" min-width="135"><template #default="{row}">{{money(row.amount_cents)}}</template></el-table-column><el-table-column label="履约期间" min-width="180"><template #default="{row}"><span class="code">{{row.start_date}} — {{row.end_date}}</span></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='active'?'success':row.status==='pending'?'warning':row.status==='returned'?'danger':'info'">{{labels[row.status]}}</el-tag></template></el-table-column><el-table-column label="操作" width="125"><template #default="{row}"><el-button text type="primary" @click="inspect(row.id)">查看</el-button><el-button v-if="auth.writable&&['draft','returned'].includes(row.status)" text type="primary" @click="edit(row)">编辑</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="query.page" :page-size="query.size" :total="total" layout="total, prev, pager, next" @current-change="load"/></div></section>
<el-dialog v-model="open" :title="form.id?'修改合同草稿':'新建合同草稿'" width="620px" :close-on-click-modal="false"><el-alert v-if="conflict" type="warning" :closable="false" title="合同已更新，当前输入已保留。请先核对服务器版本。" class="error-box"><el-button text type="primary" @click="reloadForm">载入最新合同</el-button></el-alert><el-form label-position="top" :model="form"><div class="form-grid"><el-form-item class="wide" label="合同名称" required><el-input v-model="form.title" maxlength="120"/></el-form-item><el-form-item class="wide" label="关联客户" required><el-select v-model="form.customer_id" filterable placeholder="选择启用中的客户"><el-option v-for="c in options" :key="c.id" :label="c.name" :value="c.id"/></el-select><div v-if="form.customer_id" class="cell-sub">联系人：{{options.find(c=>c.id===form.customer_id)?.contact??'客户已停用，请重新选择'}}</div></el-form-item><el-form-item class="wide" label="合同金额（元）" required><el-input v-model="form.amount" inputmode="decimal" placeholder="如 12000.00"/></el-form-item><el-form-item label="开始日期" required><el-date-picker v-model="form.start_date" type="date" value-format="YYYY-MM-DD" placeholder="选择开始日期"/></el-form-item><el-form-item label="结束日期" required><el-date-picker v-model="form.end_date" type="date" value-format="YYYY-MM-DD" placeholder="选择结束日期"/></el-form-item></div></el-form><div class="hint">保存后为草稿状态，需在合同详情中提交审核。提交失败时，本次输入会保留在表单中。</div><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="conflict" @click="save">保存草稿</el-button></template></el-dialog>
<el-drawer :model-value="!!detail" title="合同详情" :size="'min(590px, 100vw)'" @close="detail=null"><template v-if="detail"><div class="code">CT-{{String(detail.id).padStart(5,'0')}} · 数据版本 {{detail.version}}</div><h2 class="detail-title">{{detail.title}}</h2><el-tag>{{labels[detail.status]}}</el-tag><div v-for="item in [['关联客户',detail.customer_name],['合同金额',money(detail.amount_cents)],['开始日期',detail.start_date],['结束日期',detail.end_date],['最近更新',time(detail.updated_at)]]" :key="item[0]" class="detail-line"><span>{{item[0]}}</span><span>{{item[1]}}</span></div><el-alert v-if="detailConflict" class="error-box" type="warning" :closable="false" title="其他成员已处理此合同。审核意见已保留，请刷新后核对。"><el-button text type="primary" @click="inspect(detail.id);load()">刷新合同与列表</el-button></el-alert><div v-if="auth.writable" class="dialog-footer"><el-button v-if="['draft','returned'].includes(detail.status)" @click="edit(detail)">修改草稿</el-button><el-button v-if="['draft','returned'].includes(detail.status)" type="primary" :disabled="detailConflict" @click="beginAction('submit')">提交审核</el-button><template v-if="auth.admin&&detail.status==='pending'"><el-button type="danger" plain :disabled="detailConflict" @click="beginAction('return')">退回修改</el-button><el-button type="primary" :disabled="detailConflict" @click="beginAction('approve')">审核通过</el-button></template></div><h3 class="subheading">流转记录</h3><el-timeline><el-timeline-item v-for="event in detail.events" :key="event.id" :timestamp="time(event.created_at)" placement="top"><strong>{{labels[event.action]??event.action}}</strong><div class="cell-sub">{{event.actor}}{{event.note?' · '+event.note:''}}</div></el-timeline-item></el-timeline></template></el-drawer>
<el-dialog v-model="actionOpen" :title="labels[actionType]" width="460px" :close-on-click-modal="false"><p class="muted">{{actionType==='approve'?'通过后合同进入生效状态，不能再修改草稿。':actionType==='return'?'退回后业务员可修改内容并重新提交。':'提交后进入待审核队列，等待管理员处理。'}}</p><el-input v-model="note" style="margin-top:18px" type="textarea" :rows="4" maxlength="500" show-word-limit :placeholder="actionType==='return'?'填写退回原因（必填）':'处理备注（选填）'"/><el-alert v-if="detailConflict" style="margin-top:14px" type="warning" :closable="false" title="合同已更新，意见已保留。请先核对最新状态。"/><p v-if="!actionAllowed" class="hint">合同当前为「{{labels[detail?.status??'']}}」，已不支持本次操作；可关闭窗口后查看最新详情。输入的意见仍保留在当前窗口。</p><template #footer><el-button @click="actionOpen=false">取消</el-button><el-button v-if="detailConflict&&detail" @click="inspect(detail.id);load()">刷新当前状态</el-button><el-button type="primary" :disabled="detailConflict||!actionAllowed" :loading="busy" @click="act">确认{{labels[actionType]}}</el-button></template></el-dialog></template>
